process::WFP Seed Dimension Attributes.PrologProcedure:
#Region WFP Seed Dimension Attributes
# Sets the attribute VALUES that were originally built declaratively and so do not
# survive a deploy: WFP Period (index/days/prior/FY), WFP Job Family (Pay Index),
# WFP Entity, WFP Version, WFP Cost Centre. Idempotent — safe to re-run.

# --- WFP Period: Period Index (chronological), Days In Month, Prior Period, FY ---
cPer   = 'WFP Period';
nCount = DIMSIZ( cPer );
nIdx   = 0;
vPrev  = '';
nE = 1;
WHILE( nE <= nCount );
   vPer = DIMNM( cPer, nE );
   # leaf months are numeric elements named YYYY-MM
   IF( DTYPE( cPer, vPer ) @= 'N' & LONG( vPer ) = 7 & SUBST( vPer, 5, 1 ) @= '-' );
      nIdx = nIdx + 1;
      nMon = NUMBR( SUBST( vPer, 6, 2 ) );
      nDays = 31;
      IF( nMon = 2 );
         nDays = 28;
      ENDIF;
      IF( nMon = 4 % nMon = 6 % nMon = 9 % nMon = 11 );
         nDays = 30;
      ENDIF;
      AttrPutN( nIdx,  cPer, vPer, 'Period Index' );
      AttrPutN( nDays, cPer, vPer, 'Days In Month' );
      AttrPutS( vPrev, cPer, vPer, 'Prior Period' );
      AttrPutS( 'FY' | SUBST( vPer, 1, 4 ), cPer, vPer, 'FY' );
      vPrev = vPer;
   ENDIF;
   nE = nE + 1;
END;

# --- WFP Job Family: Pay Index ---
vJF = 'Engineering;1.1~Product;1.08~Sales;1.05~Marketing;1~Customer Success;0.98~Finance;1~People;0.98~IT;1~Admin;0.92~Leadership;1.15~';
WHILE( SCAN( '~', vJF ) > 1 );
   nS = SCAN( '~', vJF ); vRec = SUBST( vJF, 1, nS - 1 ) | ';'; vJF = SUBST( vJF, nS + 1, LONG( vJF ) - nS );
   nS = SCAN( ';', vRec ); vFam = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); nPi  = NUMBR( SUBST( vRec, 1, nS - 1 ) );
   IF( DIMIX( 'WFP Job Family', vFam ) > 0 );
      AttrPutN( nPi, 'WFP Job Family', vFam, 'Pay Index' );
   ENDIF;
END;

# --- WFP Entity: Local Currency, Primary Location, Reporting Currency ---
vEn = 'Group;;;GBP~UK Ltd;GBP;London;GBP~US Inc;USD;New York;GBP~NZ Ltd;NZD;Auckland;GBP~';
WHILE( SCAN( '~', vEn ) > 1 );
   nS = SCAN( '~', vEn ); vRec = SUBST( vEn, 1, nS - 1 ) | ';'; vEn = SUBST( vEn, nS + 1, LONG( vEn ) - nS );
   nS = SCAN( ';', vRec ); vEnt = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vLC  = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vPL  = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vRC  = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Entity', vEnt ) > 0 );
      IF( vLC @<> '' );
         AttrPutS( vLC, 'WFP Entity', vEnt, 'Local Currency' );
      ENDIF;
      IF( vPL @<> '' );
         AttrPutS( vPL, 'WFP Entity', vEnt, 'Primary Location' );
      ENDIF;
      AttrPutS( vRC, 'WFP Entity', vEnt, 'Reporting Currency' );
   ENDIF;
END;

# --- WFP Version: Version Type (Calculated | Static), Description ---
# Budget / Forecast / Downside are Calculated (roll up to Calculating).
# Actual is Static — non-calculating, populated by the payroll load (Phase 7);
# it rolls up to Non-Calculating and the [] STET/CONTINUE guard in the cube rules
# stops all calc for it. Snapshot members are set to Static by WFP Snapshot Version.
vVr = 'Actual;Static;Actuals — non-calculating; populated by the payroll load (Phase 7)~Budget;Calculated;Approved plan being built~Forecast;Calculated;Working current model — closed months = Actual, open months own assumptions~Downside;Calculated;Self-contained downside (cost-pressure) scenario~';
WHILE( SCAN( '~', vVr ) > 1 );
   nS = SCAN( '~', vVr ); vRec = SUBST( vVr, 1, nS - 1 ) | ';'; vVr = SUBST( vVr, nS + 1, LONG( vVr ) - nS );
   nS = SCAN( ';', vRec ); vVer = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vTyp = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vDsc = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Version', vVer ) > 0 );
      AttrPutS( vTyp, 'WFP Version', vVer, 'Version Type' );
      AttrPutS( vDsc, 'WFP Version', vVer, 'Description' );
   ENDIF;
END;

# --- WFP Cost Centre: Function, CC Name ---
vCC = 'CC-ENG-PLT;R&D;Engineering - Platform~CC-ENG-APP;R&D;Engineering - Application~CC-PROD;R&D;Product Management~CC-SALES;S&M;Sales~CC-SALESOPS;S&M;Sales Operations~CC-MKT;S&M;Marketing~CC-CS;S&M;Customer Success~CC-FIN;G&A;Finance~CC-PPL;G&A;People & HR~CC-ITOPS;G&A;IT & Operations~CC-EXEC;G&A;Executive~';
WHILE( SCAN( '~', vCC ) > 1 );
   nS = SCAN( '~', vCC ); vRec = SUBST( vCC, 1, nS - 1 ) | ';'; vCC = SUBST( vCC, nS + 1, LONG( vCC ) - nS );
   nS = SCAN( ';', vRec ); vCtr = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vFun = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vNam = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Cost Centre', vCtr ) > 0 );
      AttrPutS( vFun, 'WFP Cost Centre', vCtr, 'Function' );
      AttrPutS( vNam, 'WFP Cost Centre', vCtr, 'CC Name' );
   ENDIF;
END;

process::WFP Snapshot Version.PrologProcedure:
#Region WFP Snapshot Version — copy a calculating version into a static member
# Copies pSource -> pTarget: the input cubes (Workforce Input, Assumptions, FX
# Rates, Pay Rates) AND the calculated output (Workforce Cost, Headcount).
# pTarget is created if absent, parented under Non-Calculating, and marked
# Version Type = Static, so the [] STET/CONTINUE guard in the cube rules stops
# all calc for it — it holds exactly the pSource picture at snapshot time.
# Run at month-end close (pSource = Forecast) or budget lock (pSource = Budget).
cVer = 'WFP Version';

nStop = 0;
IF( DIMIX( cVer, pSource ) = 0 );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Source version not found: ' | pSource );
   nStop = 1;
ENDIF;
IF( nStop = 0 & ATTRS( cVer, pSource, 'Version Type' ) @<> 'Calculated' );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Refused: source "' | pSource | '" is not a Calculated version.' );
   nStop = 1;
ENDIF;
IF( nStop = 0 & TRIM( pTarget ) @= '' );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Target member name is blank.' );
   nStop = 1;
ENDIF;
IF( nStop = 0 & pTarget @= pSource );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Target equals source.' );
   nStop = 1;
ENDIF;

IF( nStop = 0 );
   IF( DIMIX( cVer, pTarget ) = 0 );
      DimensionElementInsertDirect( cVer, '', pTarget, 'N' );
   ENDIF;
   AttrPutS( 'Static', cVer, pTarget, 'Version Type' );
   AttrPutS( 'Snapshot of ' | pSource | ' - ' | TIMST( NOW, '\Y-\m-\d' ), cVer, pTarget, 'Description' );
   IF( ELISANC( cVer, 'Non-Calculating', pTarget ) = 0 );
      DimensionElementComponentAdd( cVer, 'Non-Calculating', pTarget, 1 );
   ENDIF;

   nCopied = 0;

   # --- WFP Workforce Input : Period x Position x Measure ---
   cWI = 'WFP Workforce Input';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Position' ); nC = DIMSIZ( 'WFP Workforce Input Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vPos = DIMNM( 'WFP Position', nJ );
            IF( DTYPE( 'WFP Position', vPos ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vM = DIMNM( 'WFP Workforce Input Measure', nK );
                  IF( DTYPE( 'WFP Workforce Input Measure', vM ) @= 'N' );
                     nVal = CellGetN( cWI, vP, pSource, vPos, vM );
                     IF( nVal <> 0 ); CellPutN( nVal, cWI, vP, pTarget, vPos, vM ); nCopied = nCopied + 1; ENDIF;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   # --- WFP Assumptions : Period x Entity x Measure ---
   cAS = 'WFP Assumptions';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Entity' ); nC = DIMSIZ( 'WFP Assumptions Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vEnt = DIMNM( 'WFP Entity', nJ );
            IF( DTYPE( 'WFP Entity', vEnt ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vM = DIMNM( 'WFP Assumptions Measure', nK );
                  IF( DTYPE( 'WFP Assumptions Measure', vM ) @= 'N' );
                     nVal = CellGetN( cAS, vP, pSource, vEnt, vM );
                     IF( nVal <> 0 ); CellPutN( nVal, cAS, vP, pTarget, vEnt, vM ); nCopied = nCopied + 1; ENDIF;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   # --- WFP FX Rates : Period x Currency x FX Rate Type x Measure ---
   cFX = 'WFP FX Rates';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Currency' ); nC = DIMSIZ( 'WFP FX Rate Type' ); nD = DIMSIZ( 'WFP FX Rates Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vCur = DIMNM( 'WFP Currency', nJ );
            IF( DTYPE( 'WFP Currency', vCur ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vRt = DIMNM( 'WFP FX Rate Type', nK );
                  IF( DTYPE( 'WFP FX Rate Type', vRt ) @= 'N' );
                     nL = 1;
                     WHILE( nL <= nD );
                        vM = DIMNM( 'WFP FX Rates Measure', nL );
                        IF( DTYPE( 'WFP FX Rates Measure', vM ) @= 'N' );
                           nVal = CellGetN( cFX, vP, pSource, vCur, vRt, vM );
                           IF( nVal <> 0 ); CellPutN( nVal, cFX, vP, pTarget, vCur, vRt, vM ); nCopied = nCopied + 1; ENDIF;
                        ENDIF;
                        nL = nL + 1;
                     END;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   # --- WFP Pay Rates : Period x Grade x Job Family x Location x Measure ---
   cPR = 'WFP Pay Rates';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Grade' ); nC = DIMSIZ( 'WFP Job Family' ); nD = DIMSIZ( 'WFP Location' ); nE = DIMSIZ( 'WFP Pay Rates Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vG = DIMNM( 'WFP Grade', nJ );
            IF( DTYPE( 'WFP Grade', vG ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vJF = DIMNM( 'WFP Job Family', nK );
                  IF( DTYPE( 'WFP Job Family', vJF ) @= 'N' );
                     nL = 1;
                     WHILE( nL <= nD );
                        vLoc = DIMNM( 'WFP Location', nL );
                        IF( DTYPE( 'WFP Location', vLoc ) @= 'N' );
                           nMx = 1;
                           WHILE( nMx <= nE );
                              vM = DIMNM( 'WFP Pay Rates Measure', nMx );
                              IF( DTYPE( 'WFP Pay Rates Measure', vM ) @= 'N' );
                                 nVal = CellGetN( cPR, vP, pSource, vG, vJF, vLoc, vM );
                                 IF( nVal <> 0 ); CellPutN( nVal, cPR, vP, pTarget, vG, vJF, vLoc, vM ); nCopied = nCopied + 1; ENDIF;
                              ENDIF;
                              nMx = nMx + 1;
                           END;
                        ENDIF;
                        nL = nL + 1;
                     END;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   # --- WFP Workforce Cost + WFP Headcount OUTPUT : per position, at its own
   #     Home Entity / Cost Centre, for its Salary Currency + Reporting ---
   cWC = 'WFP Workforce Cost'; cHC = 'WFP Headcount';
   vPCs = 'Base|Employer Payroll Tax|Employer Pension|Benefits|Bonus|One-Time|Gross Pay|Employee Income Tax|Employee Pension|Net Pay|';
   vHMs = 'Headcount|FTE|Open Positions|';
   nB = DIMSIZ( 'WFP Position' ); nA = DIMSIZ( 'WFP Period' );
   nJ = 1;
   WHILE( nJ <= nB );
      vPos = DIMNM( 'WFP Position', nJ );
      IF( DTYPE( 'WFP Position', vPos ) @= 'N' );
         vEnt = ATTRS( 'WFP Position', vPos, 'Home Entity' );
         vCC  = ATTRS( 'WFP Position', vPos, 'Cost Centre' );
         vSC  = ATTRS( 'WFP Position', vPos, 'Salary Currency' );
         nI = 1;
         WHILE( nI <= nA );
            vP = DIMNM( 'WFP Period', nI );
            IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
               vL = vPCs;
               WHILE( SCAN( '|', vL ) > 1 );
                  nS = SCAN( '|', vL ); vPC = SUBST( vL, 1, nS - 1 ); vL = SUBST( vL, nS + 1, LONG( vL ) - nS );
                  nVal = CellGetN( cWC, vP, pSource, vEnt, vCC, vPC, vSC, vPos, 'Amount' );
                  IF( nVal <> 0 ); CellPutN( nVal, cWC, vP, pTarget, vEnt, vCC, vPC, vSC, vPos, 'Amount' ); nCopied = nCopied + 1; ENDIF;
                  nVal = CellGetN( cWC, vP, pSource, vEnt, vCC, vPC, 'Reporting', vPos, 'Amount' );
                  IF( nVal <> 0 ); CellPutN( nVal, cWC, vP, pTarget, vEnt, vCC, vPC, 'Reporting', vPos, 'Amount' ); nCopied = nCopied + 1; ENDIF;
               END;
               vL = vHMs;
               WHILE( SCAN( '|', vL ) > 1 );
                  nS = SCAN( '|', vL ); vHM = SUBST( vL, 1, nS - 1 ); vL = SUBST( vL, nS + 1, LONG( vL ) - nS );
                  nVal = CellGetN( cHC, vP, pSource, vEnt, vCC, vPos, vHM );
                  IF( nVal <> 0 ); CellPutN( nVal, cHC, vP, pTarget, vEnt, vCC, vPos, vHM ); nCopied = nCopied + 1; ENDIF;
               END;
            ENDIF;
            nI = nI + 1;
         END;
      ENDIF;
      nJ = nJ + 1;
   END;

   ASCIIOUTPUT( 'WFP_Snapshot_ok.txt', 'Snapshot ' | pSource | ' -> ' | pTarget | ' : ' | NUMBERTOSTRING( nCopied ) | ' cells copied (input + output). ' | pTarget | ' is Static under Non-Calculating.' );
ENDIF;

process::WFP Seed Hiring Plan.PrologProcedure:
#Region WFP Seed Hiring Plan — per-version hire month + attrition month
# Table: version;position;hire_month;attrition_month  (period-index values; 0 = none).
# Hire Month already includes recruiting lead time (approve month + lead).
# Budget carries nothing (flat); the rules fall back to Start/End Period attrs
# when the plan cell is 0.
cCube = 'WFP Hiring Plan';

vP =
'Forecast;ENG-007;16;0~' |
'Forecast;SLS-004;16;0~' |
'Forecast;ENG-005;16;0~' |
'Downside;ENG-002;0;16~' |
'Downside;ENG-006;0;19~' |
'Downside;ENG-008;20;0~';

WHILE( SCAN( '~', vP ) > 1 );
   nS = SCAN( '~', vP ); vRec = SUBST( vP, 1, nS - 1 ) | ';'; vP = SUBST( vP, nS + 1, LONG( vP ) - nS );
   nS = SCAN( ';', vRec ); vVer = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vPos = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); nHire = NUMBR( SUBST( vRec, 1, nS - 1 ) ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); nLeave = NUMBR( SUBST( vRec, 1, nS - 1 ) );
   IF( DIMIX( 'WFP Version', vVer ) > 0 & DIMIX( 'WFP Position', vPos ) > 0 );
      CellPutN( nHire,  cCube, vVer, vPos, 'Hire Month' );
      CellPutN( nLeave, cCube, vVer, vPos, 'Attrition Month' );
   ENDIF;
END;

process::WFP Seed Workforce Input.PrologProcedure:
#Region Seed Workforce Input — FTE + Base Salary + One-Time per active month
# Phase 4: the active window is per calculated version — WFP Hiring Plan
# Hire/Attrition Month, falling back to Start/End Period attrs when the plan is 0.
# TBH positions with no plan hire for a version are not seeded for that version.
# Actual (non-calculating) is seeded on the attribute window, non-TBH only.
cCube = 'WFP Workforce Input';
cPos  = 'WFP Position';
cPer  = 'WFP Period';
cAsm  = 'WFP Assumptions';
cHP   = 'WFP Hiring Plan';

nPosCount = DIMSIZ( cPos );
nPerCount = DIMSIZ( cPer );

vVers = 'Budget|Forecast|Downside|';

nI = 1;
WHILE( nI <= nPosCount );
   vPos = DIMNM( cPos, nI );
   IF( DTYPE( cPos, vPos ) @= 'N' );
      nFTE   = ATTRN( cPos, vPos, 'FTE' );
      nSal   = ATTRN( cPos, vPos, 'Seed Base Salary' );
      vHome  = ATTRS( cPos, vPos, 'Home Entity' );
      vStat  = ATTRS( cPos, vPos, 'Position Status' );
      vStartPd = ATTRS( cPos, vPos, 'Start Period' );
      vEndPd   = ATTRS( cPos, vPos, 'End Period' );
      nAttrStart = ATTRN( cPer, vStartPd, 'Period Index' );
      nAttrEnd   = IF( vEndPd @= '', 999, ATTRN( cPer, vEndPd, 'Period Index' ) );

      nP = 1;
      WHILE( nP <= nPerCount );
         vPer = DIMNM( cPer, nP );
         IF( DTYPE( cPer, vPer ) @= 'N' & LONG( vPer ) = 7 );
            nPidx = ATTRN( cPer, vPer, 'Period Index' );

            vVl = vVers;
            WHILE( SCAN( '|', vVl ) > 1 );
               nS = SCAN( '|', vVl ); vVer = SUBST( vVl, 1, nS - 1 ); vVl = SUBST( vVl, nS + 1, LONG( vVl ) - nS );

               nPlanHire  = CellGetN( cHP, vVer, vPos, 'Hire Month' );
               nPlanLeave = CellGetN( cHP, vVer, vPos, 'Attrition Month' );
               nStartIdx  = IF( nPlanHire > 0, nPlanHire, IF( vStat @= 'TBH', 9999, nAttrStart ) );
               nEndIdx    = IF( nPlanLeave > 0, nPlanLeave - 1, nAttrEnd );

               nCutoff   = CellGetN( cAsm, '2026-01', vVer, vHome, 'Actuals Cutoff Index' );
               nMeritIdx = CellGetN( cAsm, '2026-01', vVer, vHome, 'Merit Review Index' );
               nUplift   = CellGetN( cAsm, '2026-01', vVer, vHome, 'Merit Increase %' )
                         + CellGetN( cAsm, '2026-01', vVer, vHome, 'Promotion Budget %' );

               IF( nPidx >= nStartIdx & nPidx <= nEndIdx & nPidx > nCutoff );
                  nVerSal = nSal;
                  IF( nMeritIdx > 0 & nPidx >= nMeritIdx );
                     nVerSal = nSal * ( 1 + nUplift );
                  ENDIF;
                  CellPutN( nFTE,    cCube, vPer, vVer, vPos, 'FTE' );
                  CellPutN( nVerSal, cCube, vPer, vVer, vPos, 'Base Salary' );
               ENDIF;
            END;

            # Actual: attribute window, non-TBH only
            IF( vStat @<> 'TBH' & nPidx >= nAttrStart & nPidx <= nAttrEnd );
               nActSal = nSal;
               IF( vPos @= 'EXEC-001' & nPidx >= 13 & nPidx <= 15 );
                  nActSal = 220000;
               ENDIF;
               CellPutN( nFTE,    cCube, vPer, 'Actual', vPos, 'FTE' );
               CellPutN( nActSal, cCube, vPer, 'Actual', vPos, 'Base Salary' );
            ENDIF;
         ENDIF;
         nP = nP + 1;
      END;
   ENDIF;
   nI = nI + 1;
END;

# Sample one-time payment: CS-001 retention, 15,000 in 2026-06 (open month).
CellPutN( 15000, cCube, '2026-06', 'Forecast', 'CS-001', 'One-Time Amount' );
CellPutN( 15000, cCube, '2026-06', 'Downside', 'CS-001', 'One-Time Amount' );

